uses {IO, Proc}
import IO
import List
import String
import Regex
import Map
import Int

let dur_re = r/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/

let num s = if s == "" then 0 else Int.of_string! s

let parse_dur d =
  let c = Regex.capture dur_re d;
  match c with
  | [_, h, m, s] -> if d == "" then Error "bad duration" else Ok (num h * 3600 + num m * 60 + num s)
  | _ -> Error "bad duration"

let parse_line line =
  let parts = List.filter (fn w -> w != "") (String.split " " (String.trim line));
  match parts with
  | [name, d] -> if name == "total" then Error "bad name" else Result.map (fn t -> (name, t)) (parse_dur d)
  | _ -> Error "malformed line"

let fmt t =
  let h = t / 3600;
  let m = (t % 3600) / 60;
  let s = t % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if out == "" then "0s" else out

let lines = List.indexed (Stream.to_list (IO.stdin_lines ()))
let parsed = List.filter_map (fn (i, l) -> if String.trim l == "" then None else Some (i + 1, parse_line l)) lines
let errs = List.filter_map (fn (n, r) -> match r with | Error e -> Some (n, e) | Ok _ -> None) parsed

match errs with
| (n, e) :: _ ->
  IO.println_err "line %{n}: %{e}"
  Proc.exit 1
| [] ->
  let items = List.filter_map (fn (_, r) -> Result.to_option r) parsed;
  let m = List.fold_left (fn acc (k, t) -> Map.update k 0 (fn x -> x + t) acc) Map.empty items;
  List.each (fn k -> IO.println "%{k} %{fmt (Option.get! (Map.get k m))}") (List.sort (Map.keys m))
  IO.println "total %{fmt (List.sum (List.map (fn (_, t) -> t) items))}"
EOF
