import Map
import Decode
import Stream

let dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let pct sorted n p =
  let r = (p * n + 99) / 100;
  List.get! (r - 1) sorted

let step (m, skipped) line =
  if String.trim line == "" then (m, skipped)
  else
    match Decode.run dec line with
    | Ok (e, v) when v >= 0 -> (Map.update e (fn o -> match o with
        | Some l -> Some (v :: l)
        | None -> Some [v]) m, skipped)
    | _ -> (m, skipped + 1)

let (groups, skipped) = IO.stdin_lines () |> Stream.fold_left step (Map.empty, 0)
Map.keys groups |> List.sort |> List.each (fn k ->
  let s = List.sort (Map.get! k groups);
  let n = List.length s;
  IO.println "%{k} count=%{n} p50=%{pct s n 50} p95=%{pct s n 95}")
if skipped > 0 then IO.println "skipped %{skipped}" else ()
EOF
